const items = [];

function addGroup({ scope, department, category, source = "", owner = department }, rows) {
  for (const row of rows) {
    const [name, problem, effect, priority, budget, unit = "комплект", criterion = "", condition = ""] = row;
    let scores = priority === "M" ? [4, 4, 4, 4] : priority === "S" ? [3, 4, 3, 4] : [2, 2, 3, 3];
    const lower = `${category} ${name}`.toLowerCase();
    if (/безопас|пожар|медицин|эвакуа|сближ|пыль|шум|вибрац|блокиров/.test(lower)) scores[0] = priority === "M" ? 5 : priority === "S" ? 4 : 3;
    if (/ремонт|диагност|запас|резерв|шины|гсм|связ|питани|дорог|телеметр|диспетчер/.test(lower)) scores[1] = priority === "M" ? 5 : priority === "S" ? 4 : 3;
    if (/пилот|после тэо|при подтверждении|если входит/.test(condition.toLowerCase())) scores[3] = 2;
    items.push({ scope, department, category, name, problem, effect, priority, budget, unit, criterion, condition, source, owner, scores });
  }
}

